"""One real retained pair of original Python programs, six generated bytes.

Requires inherited caller-owned CPU FDs. No SDK, Unison, media, compiler or
canonical IO. A failure retains the live test owner and private evidence.
"""
import hashlib
import json
import os
from pathlib import Path
import sys
import tempfile
import time
import unittest
from shared_cpu_pool import UnresolvedOwnership
from shared_process_owner import retain_after_record
from sdk_merge_receiving.store import Store
from sdk_merge_receiving.transport import run
from sdk_merge_receiving.evidence import bind

ROOT=Path(__file__).resolve().parents[1]

class ActualPair(unittest.TestCase):
    def test_original_python_pair_reaps_and_binds_six_byte_protocol(self):
        fds=tuple(json.loads(os.environ['UNISON_MERGE_CONTROL_FDS']))
        self.assertEqual(len(fds),4)
        before=[(os.fstat(fd).st_dev,os.fstat(fd).st_ino) for fd in fds]
        root=Path(tempfile.mkdtemp(prefix='u-mgp-',dir='/private/tmp'))
        st=root.stat();identity=dict(device=st.st_dev,inode=st.st_ino)
        store=Store(str(root),identity);socket_path=str(root/'once.sock')
        binary=root/'original-server.py';proxy=root/'original-proxy.py';client=root/'original-client.py'
        binary.write_text('#!'+sys.executable+'\nimport sys\n'
            'assert sys.argv[1:]==["-server","__new-rpc-mode"]\n'
            'data=sys.stdin.buffer.read();assert data==b"abc"\n'
            'sys.stdout.buffer.write(data.upper());sys.stdout.buffer.flush()\n')
        binary.chmod(0o700)
        imports='import sys,os,json,time\nsys.path[:0]='+repr([str(ROOT),str(ROOT/'sdk_host_matrix')])+'\n'
        proxy.write_text(imports+
            'from sdk_merge_receiving.proxy import serve\nfrom sdk_merge_receiving.store import Store\n'
            'from shared_cpu_pool import UnresolvedOwnership\nfrom shared_process_owner import retain_after_record\n'
            'store=Store('+repr(str(root))+','+repr(identity)+')\n'
            'cpu=[(os.fstat(fd).st_dev,os.fstat(fd).st_ino) for fd in json.loads(os.environ["UNISON_MERGE_CONTROL_FDS"])]\n'
            'store.write("PROXY-INHERITED.json",dict(cpu=cpu))\n'
            'try:\n result=serve('+repr(socket_path)+','+repr(str(binary))+',[],time.monotonic()+10)\n'
            ' store.write("PROXY.json",result)\n store.close()\n'
            'except UnresolvedOwnership as error:\n retain_after_record(lambda:print(repr(error),file=sys.stderr,flush=True))\n')
        client.write_text(imports+
            'from sdk_merge_receiving.launcher import launch\n'
            'from private_camera_receiving.close import close_descriptors\n'
            'from shared_cpu_pool import UnresolvedOwnership\nfrom shared_process_owner import retain_after_record\n'
            'cpu=[(os.fstat(fd).st_dev,os.fstat(fd).st_ino) for fd in json.loads(os.environ["UNISON_MERGE_CONTROL_FDS"])]\n'
            'read_in,write_in=os.pipe();read_out,write_out=os.pipe()\n'
            'try:\n os.write(write_in,b"abc");close_descriptors([write_in])\n'
            ' counts=launch(['+repr(str(binary))+',"-server","__new-rpc-mode"],'+repr(str(binary))+','+repr(socket_path)+
            ',time.monotonic()+10,input_fd=read_in,output_fd=write_out)\n'
            ' close_descriptors([write_out]);answer=os.read(read_out,4)\n'
            ' assert answer==b"ABC"\n close_descriptors([read_in,read_out])\n'
            ' print(json.dumps(dict(answer=answer.decode(),counts=counts,cpu=cpu)))\n'
            'except UnresolvedOwnership as error:\n retain_after_record(lambda:print(repr(error),file=sys.stderr,flush=True))\n')
        for script in (binary,proxy,client):compile(script.read_text(),str(script),'exec')
        client_command=[sys.executable,'-B',str(client)];proxy_command=[sys.executable,'-B',str(proxy)]
        try:
            pair=run(client_command,dict(os.environ),proxy_command=proxy_command,
                proxy_environment=dict(os.environ),socket_path=socket_path,deadline=time.monotonic()+12,
                pass_fds=fds,read_proxy=lambda:json.loads(store.read('PROXY.json')))
            raw=store.read('PROXY.json')
            row=dict(command=client_command,server_command=[str(binary),'-server','__new-rpc-mode'],
                     stage='seed',identity=dict(label='original-python-control',stage='seed'))
            outcome=bind(row,pair,expected_proxy_command=proxy_command,raw_proxy_bytes=raw)
            self.assertEqual(outcome['helper_record_sha256s'],[])
            client_observed=json.loads(pair['client']['stdout'])
            proxy_observed=json.loads(store.read('PROXY-INHERITED.json'))
            self.assertEqual(client_observed['answer'],'ABC')
            self.assertEqual(client_observed['cpu'],[list(x) for x in before])
            self.assertEqual(proxy_observed['cpu'],[list(x) for x in before])
            self.assertEqual(pair['raw_proxy']['forwarded_protocol_bytes'],
                             dict(client_to_server_bytes=3,server_to_client_bytes=3))
            self.assertEqual([(os.fstat(fd).st_dev,os.fstat(fd).st_ino) for fd in fds],before)
            proof=dict(scope='Original Python control only; no SDK/media/Unison/native compiled code',
                       pair=pair,raw_proxy_hex=raw.hex(),bound=outcome,
                       parent_cpu_identities=before,client_cpu_identities=client_observed['cpu'],
                       proxy_cpu_identities=proxy_observed['cpu'],source_sha256={p.name:hashlib.sha256(p.read_bytes()).hexdigest()
                           for p in (binary,proxy,client)})
            pin=store.write('PAIR-PROOF.json',proof);store.close()
            print('ORIGINAL-PAIR-PROOF '+json.dumps(dict(root=str(root),pin=pin,proof=proof)),flush=True)
        except BaseException as error:
            retain_after_record(lambda:print('ORIGINAL-PAIR-RETAINED '+str(root)+' '+repr(error),flush=True))

if __name__=='__main__':unittest.main()
